  /**
   * @method
   * @name woofipro#fetchTickers
   * @description fetches price tickers for multiple markets, statistical
   * information calculated over the past 24 hours for each market
   * @see
   * https://orderly.network/docs/build-on-omnichain/restful-api/public/get-market-info-for-all-symbols
   * @param {string[]} [symbols] unified symbols of the markets to fetch the
   * ticker for, all market tickers are returned if not assigned
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [ticker structures]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<ccxt::any>
  fetchTickers(ccxt::any symbols = ccxt::any{},
               ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 symbols = this->marketSymbols(symbols);
                 ccxt::any response =
                     awaitValue(this->v1PublicGetPublicFutures(params));
                 //
                 // {
                 //     "success": true,
                 //     "timestamp": 1786022130191,
                 //     "data": {
                 //         "rows": [{
                 //             "symbol": "PERP_BTC_USDC",
                 //             "index_price": 64185.4,
                 //             "mark_price": 64171.0,
                 //             "sum_unitary_funding": 26522.3,
                 //             "est_funding_rate": 0.0001,
                 //             "last_funding_rate": 0.00010041,
                 //             "next_funding_time": 1786032000000,
                 //             "open_interest": 110.64612,
                 //             "24h_open": 64105.6,
                 //             "24h_close": 64180.0,
                 //             "24h_high": 64941.0,
                 //             "24h_low": 63837.6,
                 //             "24h_volume": 102.2817,
                 //             "24h_amount": 6595662.199482
                 //         }]
                 //     }
                 // }
                 //
                 ccxt::any data = this->safeDict(response, std::string("data"),
                                                 ccxt::dict{});
                 ccxt::any rows =
                     this->safeList(data, std::string("rows"), ccxt::list{});
                 ccxt::any timestamp =
                     this->safeInteger(response, std::string("timestamp"));
                 ccxt::any result = ccxt::list{};
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(rows));
                      postFixIncrement(i)) {
                   ccxt::any row = ::getValue(rows, i);
                   ccxt::any marketId = this->safeString(
                       row, std::string("symbol"), std::string(""));
                   if (isTrue(isTrue((
                                  isEqual(this->markets_by_id, ccxt::any{}))) ||
                              !isTrue((inOp(this->markets_by_id, marketId))))) {
                     continue;
                   }
                   ccxt::any ticker = this->extend(
                       ccxt::dict{
                           {std::string("timestamp"), timestamp},
                       },
                       row);
                   arrayPush(result, this->parseTicker(ticker));
                 }
                 return this->filterByArrayTickers(
                     result, std::string("symbol"), symbols);
               })
        .share();
  }

  ccxt::any parseOpenInterest(ccxt::any interest,
                              ccxt::any market = ccxt::any{}) override {
    //
    //     {
    //         "symbol": "PERP_BTC_USDC",
    //         "index_price": 64185.4,
    //         "mark_price": 64171.0,
    //         "open_interest": 110.64612,
    //         "24h_open": 64105.6,
    //         "24h_close": 64180.0,
    //         "24h_high": 64941.0,
    //         "24h_low": 63837.6,
    //         "24h_volume": 102.2817,
    //         "24h_amount": 6595662.199482
    //     }
    //
    ccxt::any marketId = this->safeString(interest, std::string("symbol"));
    market = this->safeMarket(marketId, market);
    ccxt::any timestamp = this->safeInteger(interest, std::string("timestamp"));
    ccxt::any amount = this->safeNumber2(interest, std::string("open_interest"),
                                         std::string("openInterest"));
    return this->safeOpenInterest(
        ccxt::dict{
            {std::string("symbol"), ::getValue(market, std::string("symbol"))},
            {std::string("openInterestAmount"), amount},
            {std::string("openInterestValue"), ccxt::any{}},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("info"), interest},
        },
        market);
  }

